SELECT analysis_id, title, radius_m, center_lon, center_lat, intersecting_count, is_complete, analyzed_at, saved_at FROM gis_analysis_history
ORDER BY saved_at ASC, analysis_id ASC ORDER BY title ASC, analysis_id DESC ORDER BY intersecting_count DESC, saved_at DESC, analysis_id DESC ORDER BY saved_at DESC, analysis_id DESC
LIMIT #{limit} OFFSET #{offset}
